package com.hosteldekho.config; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.*; import org.springframework.security.core.context.*; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.*;
@Component public class JwtFilter extends OncePerRequestFilter { private final JwtService jwt; public JwtFilter(JwtService j){jwt=j;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{String email=jwt.email(h.substring(7));var a=new UsernamePasswordAuthenticationToken(email,null,List.of(new SimpleGrantedAuthority("ROLE_MANAGER")));SecurityContextHolder.getContext().setAuthentication(a);}catch(Exception ignored){} c.doFilter(r,s);} }
